"use strict";
const invite = document.getElementById("invite");
const panel = document.getElementById("invite-dialog");
const form = document.getElementById("invite-form");
const email = document.getElementById("email");
const error = document.getElementById("error");
const status = document.getElementById("invite-status");
invite.addEventListener("click", () => {
  status.textContent = "";
  panel.showModal();
});
document.getElementById("cancel").addEventListener("click", () => { panel.close(); });
panel.addEventListener("close", () => { invite.focus(); });
email.addEventListener("input", () => {
  if (email.validity.valid) {
    email.removeAttribute("aria-invalid");
    error.textContent = "";
  }
});
form.addEventListener("submit", (event) => {
  event.preventDefault();
  if (!email.validity.valid) {
    email.setAttribute("aria-invalid", "true");
    error.textContent = "Enter a valid email address, such as name@example.com.";
    email.focus();
    return;
  }
  const row = document.createElement("li");
  row.textContent = `Invitation sent to ${email.value}`;
  document.getElementById("invites").append(row);
  panel.close();
  status.textContent = row.textContent;
  form.reset();
  email.removeAttribute("aria-invalid");
  error.textContent = "";
});
const tabs = [...document.querySelectorAll('[role="tab"]')];
function selectTab(tab) {
  tabs.forEach((item) => {
    const selected = item === tab;
    item.tabIndex = selected ? 0 : -1;
    item.setAttribute("aria-selected", String(selected));
    document.getElementById(item.getAttribute("aria-controls")).hidden = !selected;
  });
  tab.focus();
}
tabs.forEach((tab, index) => {
  tab.addEventListener("click", () => selectTab(tab));
  tab.addEventListener("keydown", (event) => {
    if (!['ArrowLeft','ArrowRight'].includes(event.key)) return;
    event.preventDefault();
    selectTab(tabs[(index + (event.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length]);
  });
});

